import queue
upper = queue.PriorityQueue()
under = queue.PriorityQueue()
n = int(input())
nreview = 0
for _ in range(n):
	s = input()
	if len(s) != 1:
		(a, b) = map(int, s.split())
		nreview += 1
		if nreview < 3:
			under.put(-b)
		elif nreview == 3:
			under.put(-b)
			upper.put(-under.get())
		else:
			c = upper.queue[0]
			d = -under.queue[0]
			if upper.qsize() == nreview // 3:
				if c >= b:
					under.put(-b)
				else:
					upper.get()
					upper.put(b)
					under.put(-c)
			elif d > b:
				upper.put(-under.get())
				under.put(-b)
			else:
				upper.put(b)
	elif nreview < 3:
		print('No reviews yet')
	else:
		print(upper.queue[0])
